  { featureType: 'landscape', elementType: 'geometry', stylers: [{ color: '#1c1c1c' }] },
];

type Franja = 'CUALQUIERA' | 'MANANA' | 'TARDE' | 'NOCHE';
type Dia = 'CUALQUIERA' | 'HOY' | 'MANANA';

interface FiltrosUI {
  origen: string;
  destino: string;
  franja: Franja;
  dia: Dia;
}

const FILTROS_VACIOS: FiltrosUI = { origen: '', destino: '', franja: 'CUALQUIERA', dia: 'CUALQUIERA' };

// Franjas del día (la nocturna cruza la medianoche; el backend lo soporta).
const HORAS_FRANJA: Record<Exclude<Franja, 'CUALQUIERA'>, { desde: string; hasta: string }> = {
  MANANA: { desde: '05:00', hasta: '12:00' },
  TARDE:  { desde: '12:00', hasta: '18:00' },
  NOCHE:  { desde: '18:00', hasta: '05:00' },
};

const dosDigitos = (n: number) => String(n).padStart(2, '0');
const aFechaISO = (d: Date) => `${d.getFullYear()}-${dosDigitos(d.getMonth() + 1)}-${dosDigitos(d.getDate())}`;

/** Convierte los filtros de la pantalla en los parámetros que entiende el backend. */
function aFiltrosApi(f: FiltrosUI): FiltrosViajes {
  const api: FiltrosViajes = { origen: f.origen, destino: f.destino };
  if (f.franja !== 'CUALQUIERA') {
    api.horaDesde = HORAS_FRANJA[f.franja].desde;
    api.horaHasta = HORAS_FRANJA[f.franja].hasta;
  }
  if (f.dia !== 'CUALQUIERA') {
    const d = new Date();
    if (f.dia === 'MANANA') d.setDate(d.getDate() + 1);
    api.fecha = aFechaISO(d);
  }
  return api;
}

const contarFiltros = (f: FiltrosUI) =>
  (f.origen.trim() ? 1 : 0) + (f.destino.trim() ? 1 : 0) + (f.franja !== 'CUALQUIERA' ? 1 : 0) + (f.dia !== 'CUALQUIERA' ? 1 : 0);

type ViajeConRuta = Viaje & {
  routeCoords?: LatLng[];
  distanceText?: string;
  durationText?: string;
};

/** Mini-mapa de la ruta dentro de cada tarjeta, estilo Uber. */
function RouteThumbnail({ coordinates, isDark }: { coordinates: LatLng[]; isDark: boolean }) {
  if (Platform.OS === 'web' || coordinates.length === 0) return null;

  const MapView = require('react-native-maps').default;
  const { Polyline, Marker, PROVIDER_DEFAULT, PROVIDER_GOOGLE } = require('react-native-maps');
  const mapProvider = Platform.OS === 'ios' ? PROVIDER_DEFAULT : PROVIDER_GOOGLE;

  const lats = coordinates.map((c) => c.latitude);
  const lngs = coordinates.map((c) => c.longitude);
  const region = {
    latitude: (Math.min(...lats) + Math.max(...lats)) / 2,
    longitude: (Math.min(...lngs) + Math.max(...lngs)) / 2,
    latitudeDelta: Math.max(0.015, (Math.max(...lats) - Math.min(...lats)) * 1.7),
    longitudeDelta: Math.max(0.015, (Math.max(...lngs) - Math.min(...lngs)) * 1.7),
  };

  return (
    <MapView
      style={{ width: '100%', height: 110, borderRadius: 12 }}
      provider={mapProvider}
      customMapStyle={isDark ? DARK_MAP_STYLE : []}
      // Apple Maps (iOS) ignora customMapStyle y sigue el tema del sistema:
      // se fuerza al tema de la app para que no salga oscuro en modo claro.
      userInterfaceStyle={isDark ? 'dark' : 'light'}
      region={region}
      scrollEnabled={false}
      zoomEnabled={false}
      pitchEnabled={false}
      rotateEnabled={false}
      pointerEvents="none"
    >
      <Polyline coordinates={coordinates} strokeColor="#3DBE7A" strokeWidth={3} />
      <Marker coordinate={coordinates[0]} pinColor="#3DBE7A" />
      <Marker coordinate={coordinates[coordinates.length - 1]} pinColor="#DA6720" />
    </MapView>
  );
}

function AvailableTripsMap({
