                    {viaje.cuposDisponibles} {t('availableTrips.cuposCallout')} · ${viaje.aportePorPasajero}
                  </Text>
                </View>
              </Callout>
            </Marker>
          )}

          {viaje.destinoLat != null && viaje.destinoLng != null && (
            <Marker
              coordinate={{ latitude: viaje.destinoLat, longitude: viaje.destinoLng }}
              pinColor={C.orange}
              onPress={() => onSelect(viaje)}
            />
          )}
        </View>
      ))}
    </MapView>
  );
}

export default function AvailableTripsScreen() {
  const { t } = useTranslation();
  const { isDark } = useAppTheme();
  const C = isDark ? DARK_C : LIGHT_C;
  const s = useMemo(() => createStyles(C), [C]);
  const router = useRouter();
  const { usuario } = useAuth();
  const [viajes, setViajes] = useState<ViajeConRuta[]>([]);
  const [viajeSeleccionado, setViajeSeleccionado] = useState<ViajeConRuta | null>(null);
  const [cargando, setCargando] = useState(true);
  const [reservandoId, setReservandoId] = useState<string | null>(null);
  const [error, setError] = useState('');

  // ── Filtros de búsqueda (UR-006): zona, destino, día y franja horaria ──
  const [filtros, setFiltros] = useState<FiltrosUI>(FILTROS_VACIOS);
  const [mostrarFiltros, setMostrarFiltros] = useState(false);
  const [buscando, setBuscando] = useState(false);
  const filtrosRef = useRef<FiltrosUI>(FILTROS_VACIOS);
  const cantidadFiltros = contarFiltros(filtros);

  // `completa` = pantalla de carga completa (primer ingreso / al volver a la pantalla).
  // Al cambiar un filtro solo se muestra un indicador pequeño para no desmontar los campos de texto.
  const cargar = useCallback(async (completa: boolean = true) => {
    if (completa) setCargando(true);
    else setBuscando(true);
    setError('');
    try {
      const data = await listarViajes(aFiltrosApi(filtrosRef.current));
      const disponibles = data
        .filter(
          (v) =>
            v.estado === 'PROGRAMADO' &&
            v.cuposDisponibles > 0 &&
            v.conductorId !== usuario?.id &&
            v.origenLat != null &&
            v.origenLng != null
        )
        .sort(
          (a, b) =>
            new Date(a.fechaHoraSalida).getTime() - new Date(b.fechaHoraSalida).getTime()
        );

      const conRutas = await Promise.all(
        disponibles.map(async (viaje) => {
          if (viaje.destinoLat == null || viaje.destinoLng == null) return viaje;
          try {
            const info = await getRoute(
              { lat: viaje.origenLat!, lng: viaje.origenLng! },
              { lat: viaje.destinoLat, lng: viaje.destinoLng }
            );
            return {
              ...viaje,
              routeCoords: info.coordinates,
              distanceText: info.distanceText,
              durationText: info.durationText,
            };
          } catch {
            return viaje;
          }
        })
      );

      setViajes(conRutas);
      setViajeSeleccionado((actual) =>
        actual && conRutas.some((v) => v.id === actual.id) ? actual : null
      );
    } catch (e: any) {
      setError(e?.message ?? t('availableTrips.errorLoad'));
    } finally {
      setCargando(false);
      setBuscando(false);
    }
  }, [usuario?.id]);

  // Al cambiar un filtro se vuelve a buscar (con una pequeña espera mientras el usuario escribe).
  const primerRender = useRef(true);
  useEffect(() => {
    if (primerRender.current) {
      primerRender.current = false;
      return;
    }
    const id = setTimeout(() => {
      filtrosRef.current = filtros;
      cargar(false);
    }, 450);
    return () => clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filtros]);

  const limpiarFiltros = () => setFiltros(FILTROS_VACIOS);

  useFocusEffect(
    useCallback(() => {
      cargar(true);
    }, [cargar])
  );

  const reservar = async (viaje: Viaje) => {
    setReservandoId(viaje.id);
    try {
      await solicitarReserva({ viajeId: viaje.id });
      Alert.alert(t('availableTrips.reservaEnviadaTitle'), t('availableTrips.reservaEnviadaMsg'));
      setViajeSeleccionado(null);
      await cargar();
    } catch (e: any) {
      Alert.alert(t('availableTrips.noSePudoReservarTitle'), e?.message ?? t('availableTrips.intentaDeNuevo'));
    } finally {
      setReservandoId(null);
    }
  };

  return (
    <SafeAreaView style={s.root}>
      <View style={s.header}>
        <TouchableOpacity onPress={() => router.back()} style={s.back} activeOpacity={0.7}>
          <Text style={s.backText}>‹</Text>
        </TouchableOpacity>
        <Text style={s.title}>{t('availableTrips.title')}</Text>
        <TouchableOpacity
          onPress={() => setMostrarFiltros((v) => !v)}
          style={s.filterToggle}
          activeOpacity={0.7}
          accessibilityRole="button"
          accessibilityLabel={t('availableTrips.filtros')}
        >
          <Ionicons
            name={mostrarFiltros ? 'options' : 'options-outline'}
            size={24}
            color={cantidadFiltros > 0 ? C.green : C.text}
          />
          {cantidadFiltros > 0 && (
            <View style={s.filterBadge}>
              <Text style={s.filterBadgeText}>{cantidadFiltros}</Text>
            </View>
          )}
        </TouchableOpacity>
      </View>

      {mostrarFiltros && (
        <View style={s.filterPanel}>
          <View style={s.filterRow}>
            <View style={s.filterInputWrap}>
              <Ionicons name="location-outline" size={16} color={C.muted} />
              <TextInput
                style={s.filterInput}
                value={filtros.origen}
                onChangeText={(v) => setFiltros((f) => ({ ...f, origen: v }))}
                placeholder={t('availableTrips.filtroOrigen')}
                placeholderTextColor={C.muted}
                autoCorrect={false}
                returnKeyType="search"
              />
            </View>
            <View style={s.filterInputWrap}>
              <Ionicons name="flag-outline" size={16} color={C.muted} />
              <TextInput
                style={s.filterInput}
                value={filtros.destino}
                onChangeText={(v) => setFiltros((f) => ({ ...f, destino: v }))}
                placeholder={t('availableTrips.filtroDestino')}
                placeholderTextColor={C.muted}
                autoCorrect={false}
                returnKeyType="search"
              />
            </View>
          </View>

          <Text style={s.filterLabel}>{t('availableTrips.filtroDia')}</Text>
          <View style={s.chipRow}>
            {(['CUALQUIERA', 'HOY', 'MANANA'] as Dia[]).map((d) => (
              <TouchableOpacity
                key={d}
                style={[s.chip, filtros.dia === d && s.chipActive]}
                onPress={() => setFiltros((f) => ({ ...f, dia: d }))}
                activeOpacity={0.8}
              >
                <Text style={[s.chipText, filtros.dia === d && s.chipTextActive]}>
                  {t(`availableTrips.dia_${d}`)}
                </Text>
              </TouchableOpacity>
            ))}
          </View>

          <Text style={s.filterLabel}>{t('availableTrips.filtroHora')}</Text>
          <View style={s.chipRow}>
            {(['CUALQUIERA', 'MANANA', 'TARDE', 'NOCHE'] as Franja[]).map((fr) => (
              <TouchableOpacity
                key={fr}
                style={[s.chip, filtros.franja === fr && s.chipActive]}
                onPress={() => setFiltros((f) => ({ ...f, franja: fr }))}
                activeOpacity={0.8}
              >
                <Text style={[s.chipText, filtros.franja === fr && s.chipTextActive]}>
                  {t(`availableTrips.franja_${fr}`)}
                </Text>
              </TouchableOpacity>
            ))}
          </View>

          <View style={s.filterFooter}>
            {buscando ? <ActivityIndicator size="small" color={C.green} /> : <View />}
            {cantidadFiltros > 0 && (
              <TouchableOpacity onPress={limpiarFiltros} activeOpacity={0.7}>
                <Text style={s.filterClear}>{t('availableTrips.limpiarFiltros')}</Text>
              </TouchableOpacity>
            )}
          </View>
        </View>
      )}

      {cargando ? (
        <View style={s.center}>
          <ActivityIndicator size="large" color={C.green} />
          <Text style={s.loadingText}>{t('availableTrips.loadingText')}</Text>
        </View>
      ) : error ? (
        <View style={s.center}>
          <Text style={s.error}>{error}</Text>
          <TouchableOpacity onPress={() => cargar(true)} style={s.retry}>
            <Text style={s.retryText}>{t('availableTrips.retry')}</Text>
          </TouchableOpacity>
        </View>
      ) : (
        <View style={{ flex: 1 }}>
          {/* El mapa ocupa la parte superior, igual que la vista de ruta del flujo de publicación. */}
          <View style={s.mapContainer}>
            <AvailableTripsMap
              viajes={viajes}
              selectedId={viajeSeleccionado?.id ?? null}
              onSelect={setViajeSeleccionado}
            />
            <View style={s.mapBadge}>
              <Text style={s.mapBadgeText}>{viajes.length} {t('availableTrips.mapBadge')}</Text>
            </View>
          </View>

          <ScrollView
            contentContainerStyle={s.content}
            showsVerticalScrollIndicator={false}
          >
            {viajes.length === 0 ? (
              <View style={s.empty}>
                <Text style={s.emptyTitle}>{t('availableTrips.emptyTitle')}</Text>
                <Text style={s.emptyText}>
                  {cantidadFiltros > 0 ? t('availableTrips.emptyFiltrosText') : t('availableTrips.emptyText')}
                </Text>
                {cantidadFiltros > 0 && (
                  <TouchableOpacity style={s.retry} onPress={limpiarFiltros} activeOpacity={0.8}>
                    <Text style={s.retryText}>{t('availableTrips.limpiarFiltros')}</Text>
                  </TouchableOpacity>
                )}
              </View>
            ) : (
              <>
                <Text style={s.sectionTitle}>{t('availableTrips.sectionTitle')}</Text>
                {viajes.map((viaje) => {
                  const seleccionado = viajeSeleccionado?.id === viaje.id;
                  return (
                    <TouchableOpacity
                      key={viaje.id}
                      style={[s.card, seleccionado && s.cardSelected]}
                      onPress={() => setViajeSeleccionado(viaje)}
                      activeOpacity={0.85}
                    >
                      <View style={s.cardHeader}>
                        <Text style={s.driver}>{viaje.conductorNombre}</Text>
                        <Text style={s.price}>${viaje.aportePorPasajero}</Text>
                      </View>

                      {!!viaje.routeCoords?.length && (
                        <View style={s.thumbnailWrap}>
                          <RouteThumbnail coordinates={viaje.routeCoords} isDark={isDark} />
                        </View>
                      )}

                      <Text style={s.route}>{viaje.origenDescripcion}</Text>
                      <Text style={s.arrow}>↓</Text>
                      <Text style={s.route}>{viaje.destinoDescripcion}</Text>

                      <View style={s.infoRow}>
                        <Text style={s.info}>
                          {new Date(viaje.fechaHoraSalida).toLocaleString('es-CO', {
                            dateStyle: 'medium',
                            timeStyle: 'short',
                          })}
                        </Text>
                        <Text style={s.seats}>{viaje.cuposDisponibles} {t('availableTrips.cupoSingular')}</Text>
                      </View>

                      {(!!viaje.distanceText || !!viaje.durationText) && (
                        <View style={s.routeStatsRow}>
                          {!!viaje.distanceText && <Text style={s.routeStatText}>📍 {viaje.distanceText}</Text>}
                          {!!viaje.durationText && <Text style={s.routeStatText}>🕐 {viaje.durationText}</Text>}
                        </View>
                      )}

                      {seleccionado && (
                        <TouchableOpacity
                          style={s.reserve}
                          disabled={reservandoId === viaje.id}
                          onPress={() => reservar(viaje)}
                          activeOpacity={0.8}
                        >
                          {reservandoId === viaje.id ? (
                            <ActivityIndicator color="#FFFFFF" />
                          ) : (
                            <Text style={s.reserveText}>{t('availableTrips.reservar')}</Text>
                          )}
                        </TouchableOpacity>
                      )}
                    </TouchableOpacity>
                  );
                })}
              </>
            )}
          </ScrollView>
        </View>
      )}
    </SafeAreaView>
  );
}

