    iniciarSesion,
    iniciarSesionConBiometria,
    biometricDisponible,
    biometricActivada,
    haySesionGuardada,
    habilitarBiometria,
  } = useAuth();

  const [usuario,      setUsuario]      = useState('');
  const [password,     setPassword]     = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [focused,      setFocused]      = useState<'usuario' | 'password' | null>(null);
  const [cargando,     setCargando]     = useState(false);
  const [verificandoBiometria, setVerificandoBiometria] = useState(false);
  const [error,        setError]        = useState('');

  // UR-002: bloqueo de la biometría tras 3 intentos fallidos
  const [bloqueo,         setBloqueo]         = useState<EstadoBloqueoBiometrico | null>(null);
  const [mostrarDesbloqueo, setMostrarDesbloqueo] = useState(false);

  const mostrarBotonBiometrico = biometricDisponible && biometricActivada && haySesionGuardada;
  const intentoAutomaticoHecho = useRef(false);

  // Prellena el campo con el último usuario que inició sesión en este equipo.
  useEffect(() => {
    obtenerUltimoUsuario().then((u) => {
      if (u) setUsuario(u);
    });
  }, []);

  // Lee cuántos intentos biométricos fallidos lleva el dispositivo.
  useEffect(() => {
    obtenerEstadoBloqueoBiometrico().then(setBloqueo).catch(() => {});
  }, []);

  const biometriaBloqueada = !!bloqueo?.bloqueada;

  // Si ya hay una sesión activa (se retomó sola porque la biometría no
  // estaba protegiéndola) o se abre luego de desbloquear, entra directo.
  useEffect(() => {
    if (!cargandoSesion && sesionActiva) {
      router.replace('/home');
    }
  }, [cargandoSesion, sesionActiva, router]);

  // Al llegar a esta pantalla con biometría disponible y una sesión guardada,
  // lanza el prompt de huella/rostro automáticamente una sola vez, como
  // hacen Nequi o Davivienda al abrir la app.
  useEffect(() => {
    if (
      !cargandoSesion &&
      bloqueo !== null &&
      !biometriaBloqueada &&
      mostrarBotonBiometrico &&
      !sesionActiva &&
      !intentoAutomaticoHecho.current
    ) {
      intentoAutomaticoHecho.current = true;
      handleBiometria();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cargandoSesion, mostrarBotonBiometrico, sesionActiva, bloqueo]);

  const handleBiometria = async () => {
    setError('');

    // Ya agotó los 3 intentos: solo se desbloquea con el código del correo.
    const estadoPrevio = await obtenerEstadoBloqueoBiometrico();
    setBloqueo(estadoPrevio);
    if (estadoPrevio.bloqueada) {
      abrirDesbloqueo();
      return;
    }

    setVerificandoBiometria(true);
    try {
      const ok = await iniciarSesionConBiometria();
      if (ok) {
        router.replace('/home');
      } else {
        const estado = await obtenerEstadoBloqueoBiometrico();
        setBloqueo(estado);
        setError(
          estado.bloqueada
            ? t('login.biometricLocked')
            : estado.intentosFallidos > 0
            ? t('login.biometricAttemptsLeft', { n: estado.intentosRestantes })
            : t('login.errorBiometric'),
        );
      }
    } finally {
      setVerificandoBiometria(false);
    }
  };

  const abrirDesbloqueo = () => {
    if (!usuario.trim()) {
      setError(t('login.errorUsernameRequired'));
      return;
    }
    setMostrarDesbloqueo(true);
  };

  const handleDesbloqueado = async () => {
    setMostrarDesbloqueo(false);
    setError('');
    setBloqueo(await obtenerEstadoBloqueoBiometrico());
    Alert.alert(t('login.biometricUnlockedTitle'), t('login.biometricUnlockedMsg'));
  };

  const handleLogin = async () => {
    setError('');

    if (!usuario.trim()) {
      setError(t('login.errorUsernameRequired'));
      return;
    }
    if (!password) {
      setError(t('login.errorPasswordRequired'));
      return;
    }

    // Acceso de administrador: se valida en el backend (POST /api/admin/login).
    if (esUsuarioAdmin(usuario)) {
      setCargando(true);
      try {
        await loginAdmin(usuario, password);
        setPassword('');
        router.replace('/admin');
      } catch (e: any) {
        setError(e?.message ?? t('login.errorGeneric'));
      } finally {
        setCargando(false);
      }
      return;
    }

    setCargando(true);
    try {
      const email = construirEmailDesdeUsuario(usuario);
      await iniciarSesion({ email, password });
      await guardarUltimoUsuario(extraerUsuarioDeEmail(email));

      // Si el dispositivo soporta biometría y el usuario aún no la activó,
      // se le ofrece activarla para no tener que escribir la contraseña
      // la próxima vez que abra la app.
      if (biometricDisponible && !biometricActivada) {
        Alert.alert(
          t('login.biometricAlertTitle'),
          t('login.biometricAlertMessage'),
          [
            { text: t('login.biometricAlertNotNow'), style: 'cancel', onPress: () => router.replace('/home') },
            {
              text: t('login.biometricAlertEnable'),
              onPress: async () => {
                await habilitarBiometria();
                router.replace('/home');
              },
            },
          ],
        );
      } else {
        router.replace('/home');
      }
    } catch (err: any) {
      setError(err.message ?? t('login.errorGeneric'));
    } finally {
      setCargando(false);
    }
  };

  return (
    <KeyboardAvoidingView
      style={s.flex}
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
    >
      <View style={s.container}>

        <Text style={s.title}>{t('login.title')}</Text>

        {/* Usuario */}
        <View style={s.fieldGroup}>
          <Text style={s.label}>{t('login.usernameLabel')}</Text>
          <View style={[s.inputWrap, focused === 'usuario' && s.inputWrapFocus]}>
            <Text style={s.icon}>@</Text>
            <TextInput
              style={s.input}
              placeholder={t('login.usernamePlaceholder')}
              placeholderTextColor={C.iconMuted}
              autoCapitalize="none"
              autoCorrect={false}
              keyboardType="email-address"
              returnKeyType="next"
              value={usuario}
              onChangeText={setUsuario}
              onFocus={() => setFocused('usuario')}
              onBlur={() => setFocused(null)}
            />
            <Text style={s.dominio}>{DOMINIO_CORREO}</Text>
          </View>
        </View>

        {/* Password */}
        <View style={s.fieldGroup}>
          <Text style={s.label}>{t('login.passwordLabel')}</Text>
          <View style={[s.inputWrap, focused === 'password' && s.inputWrapFocus]}>
            <Text style={s.icon}>◉</Text>
            <TextInput
              style={[s.input, { flex: 1 }]}
              placeholder={t('login.passwordPlaceholder')}
              placeholderTextColor={C.iconMuted}
              secureTextEntry={!showPassword}
              returnKeyType="done"
              value={password}
              onChangeText={setPassword}
              onFocus={() => setFocused('password')}
              onBlur={() => setFocused(null)}
              onSubmitEditing={handleLogin}
            />
            <Pressable onPress={() => setShowPassword(p => !p)} hitSlop={8}>
              <Text style={s.icon}>{showPassword ? '◎' : '⊗'}</Text>
            </Pressable>
          </View>
        </View>

        {/* Error message */}
        {!!error && (
          <View style={s.errorBox}>
            <Text style={s.errorText}>{error}</Text>
          </View>
        )}

        {/* Sign In button */}
        <TouchableOpacity
          style={[s.signInBtn, cargando && s.signInBtnDisabled]}
          activeOpacity={0.88}
          onPress={handleLogin}
          disabled={cargando}
        >
          {cargando
            ? <ActivityIndicator color={C.primaryText} />
            : <Text style={s.signInBtnText}>{t('login.signInButton')}</Text>
          }
        </TouchableOpacity>

        {/* Biometría se solicita automáticamente al abrir la app. Este botón queda como reintento. */}
        {mostrarBotonBiometrico && !biometriaBloqueada && (
          <TouchableOpacity
            style={[s.bioBtn, verificandoBiometria && s.signInBtnDisabled]}
            activeOpacity={0.85}
            onPress={handleBiometria}
            disabled={verificandoBiometria}
          >
            {verificandoBiometria ? (
              <ActivityIndicator color={C.accentGreen} />
            ) : (
              <>
                <Text style={s.bioIcon}>🔒</Text>
                <Text style={s.bioBtnText}>{t('login.biometricButton')}</Text>
              </>
            )}
          </TouchableOpacity>
        )}

        {/* UR-002: tras 3 intentos fallidos la biometría se bloquea hasta ingresar el código del correo. */}
        {mostrarBotonBiometrico && biometriaBloqueada && (
          <View style={s.lockBox}>
            <Text style={s.lockTitle}>{t('login.biometricLockedTitle')}</Text>
            <Text style={s.lockText}>{t('login.biometricLockedText')}</Text>
            <TouchableOpacity style={s.lockBtn} activeOpacity={0.85} onPress={abrirDesbloqueo}>
              <Text style={s.lockBtnText}>{t('login.biometricUnlockButton')}</Text>
            </TouchableOpacity>
          </View>
        )}

        <TouchableOpacity style={s.forgotBtn} onPress={() => router.push('/forgot-password')}>
          <Text style={s.forgotText}>{t('login.forgotPassword')}</Text>
        </TouchableOpacity>

        <View style={s.footer}>
          <Text style={s.footerText}>{t('login.noAccount')}</Text>
          <TouchableOpacity onPress={() => router.push('/register')}>
            <Text style={s.footerLink}>{t('login.registerLink')}</Text>
          </TouchableOpacity>
        </View>

      </View>

      <BiometricUnlockModal
        visible={mostrarDesbloqueo}
        usuario={usuario}
        C={C}
        onClose={() => setMostrarDesbloqueo(false)}
        onUnlocked={handleDesbloqueado}
      />
    </KeyboardAvoidingView>
  );
}

